/* Real Chromium against production bundle; synthetic examples generated by real APIs. */
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const root=path.resolve(__dirname,'../..'),output=process.argv[2],fixturePath=process.argv[3];
if(!output||fs.existsSync(output)||!fixturePath)throw Error('NEW output path and fixture required');
const fixture=JSON.parse(fs.readFileSync(fixturePath));const {chromium}=require(process.env.PLAYWRIGHT_MODULE_DIR+'/playwright');
const delay=ms=>new Promise(r=>setTimeout(r,ms));
(async()=>{const started=performance.now(),results=[],errors=[],external=[],calls=[];
 const browser=await chromium.launch({headless:true,executablePath:process.env.BROWSER_EXECUTABLE});const context=await browser.newContext({viewport:{width:1440,height:1050}});const page=await context.newPage();page.setDefaultTimeout(6500);page.on('pageerror',e=>errors.push(e.message));
 let control={};const first=fixture.datasets[0],pdf=fixture.datasets[1],mainCandidate=first.responses['/candidates'].candidates[0];
 const safeJob=(ds,state)=>({...ds.job,state,events:state==='completed'?ds.job.events:[],attempt:state==='queued'?0:1,...(state==='failed'?{error_code:'workflow_internal_failure',error_category:'RETRYABLE'}:{error_code:null,error_category:null})});
 await page.route('**/*',async route=>{const req=route.request(),u=new URL(req.url());
  if(u.origin!=='http://127.0.0.1:4173'){external.push(u.origin);return route.abort();}
  const reply=(body,status=200)=>route.fulfill({status,contentType:'application/json',body:JSON.stringify(body)});
  if(u.pathname.startsWith('/api/')){calls.push({path:u.pathname,method:req.method(),headers:req.headers()});
   if(u.pathname==='/api/auth/status'){await delay(control.authDelay||0);return reply({provider_available:!control.unavailable,remote_enabled:control.remoteFlag??false});}
   if(u.pathname==='/api/auth/me')return control.anonymous?reply({},401):reply({user_id:'synthetic-reviewer',institution_id:'A',institution_name:'합성 연구지원기관',role:control.role||'manager',institution_admin:true,csrf_token:'synthetic-csrf'});
   if(u.pathname==='/api/documents'&&req.method()==='POST'){return reply({document:doc(),duplicate:false},201);}
   if(u.pathname==='/api/documents'){const docs=structuredClone(fixture.documents).map(d=>d.id===first.document.id?doc():d);if(control.foreignList)docs[0].institution_id='B';if(control.deregister)docs[0].registered=false;if(control.inactive)docs[0].active=false;return reply(docs);}
   const match=u.pathname.match(/^\/api\/documents\/([^/]+)\/versions\/([^/]+)(.*)$/);if(!match)return reply({},404);
   const ds=fixture.datasets.find(x=>x.document.document_id===match[1]&&x.document.id===match[2]);if(!ds){const doc=fixture.documents.find(d=>d.document_id===match[1]&&d.id===match[2]);return reply(doc||{},doc?200:404);}
   const tail=match[3];if(!tail){if(control.active&&control.failVerification)return reply({},500);if(control.deregister)return reply({},404);return reply(ds===first?doc():ds.document);}
   if(tail==='/parsing')return reply({id:'parse-'+match[2],version_id:match[2],state:control.parseState||'completed',attempt:control.newAttempt?2:1});
   if(tail==='/parsing/retry')return reply({id:'parse-'+match[2],version_id:match[2],state:'queued',attempt:2});
   if(tail.startsWith('/chunk-jobs')){if(req.method()==='POST'){assert.equal(req.headers()['x-csrf-token'],'synthetic-csrf');control.chunks=(control.chunks||0)+1;}return reply({id:'chunk-'+match[2],version_id:control.mixedChunk?'wrong':match[2],state:control.chunkState||'completed',parse_job_id:'parse-'+match[2],parse_attempt:1,attempt:1,generation:1});}
   if(tail==='/activate'){assert.equal(req.method(),'POST');assert.equal(req.headers()['x-csrf-token'],'synthetic-csrf');control.activations=(control.activations||0)+1;await delay(control.activateDelay||0);if(control.activateLost){control.active=true;return route.abort();}if(control.activateNetwork)return route.abort();if(control.activateError)return reply({},control.activateError);control.active=true;return reply(doc());}
   if(tail==='/original'){await delay(control.pdfDelay||0);return route.fulfill({status:200,contentType:'application/pdf',body:Buffer.from(ds.original_pdf_base64,'base64')});}
   if(tail.includes('/chunks/')){if(control.resolveDelay)await delay(control.resolveDelay);if(control.resolveMissing)return reply({},404);if(control.resolveNetwork)return route.abort();assert.equal(req.method(),'POST');assert.equal(req.headers()['x-csrf-token'],'synthetic-csrf');const ref=req.postDataJSON();let data=structuredClone(ds.resolved[ref.chunk_id]);if(control.badResolve)data.evidence.organization_id='B';return reply(data);}
   if(!tail.startsWith('/workflow'))return reply({},404);
   if(control.forbiddenAll)return reply({},403);
   const suffix=tail.slice('/workflow'.length);if(suffix==='/jobs'){assert.equal(req.method(),'POST');assert.equal(req.headers()['x-csrf-token'],'synthetic-csrf');assert.deepEqual(req.postDataJSON(),{});control.posts=(control.posts||0)+1;await delay(control.submitDelay||0);return reply(safeJob(ds,control.enqueueFailed?'failed':'queued'),202);}
   if(suffix.endsWith('/retry')){control.retries=(control.retries||0)+1;return reply(safeJob(ds,'queued'),202);}
   if(suffix.endsWith('/cancel')){control.cancels=(control.cancels||0)+1;return reply(safeJob(ds,'cancelled'));}
   if(suffix.startsWith('/jobs/')){control.polls=(control.polls||0)+1;return reply(safeJob(ds,control.neverComplete?'processing':control.polls<2?'processing':'completed'));}
   if(suffix==='/candidates'&&control.workflowError){if(control.workflowError==='network')return route.abort();return reply({},control.workflowError);}
   if(control.evidenceMissing&&suffix.endsWith('/evidence'))return reply({},404);
   if(control.evidenceDelay&&suffix.endsWith('/evidence'))await delay(control.evidenceDelay);
   if(control.late&&ds===first&&suffix==='/candidates')await delay(1200);
   let data=structuredClone(ds.responses[suffix+u.search]||ds.responses[suffix]);if(!data)return reply({},404);
   if(control.bigGraph&&suffix.startsWith('/candidates')&&!suffix.endsWith('/evidence')){const c=data.candidates[0];c.steps=[...c.steps,...Array.from({length:96},(_,i)=>({...structuredClone(c.steps[i%4]),id:'stress_'+i}))];}
   if(control.empty&&suffix==='/candidates')data.candidates=[];
   if(control.unsafe)data.semantic_verification='VERIFIED';
   if(control.mixedGeneration&&suffix.startsWith('/form-links'))data.generation_id='another-generation';
   if(control.multipleEvidence&&suffix.startsWith('/candidates')&&!suffix.endsWith('/evidence'))data.candidates[0].steps[0].actions.push(structuredClone(data.candidates[0].steps[1].label));
   if(control.foreignEvidence&&suffix.endsWith('/evidence'))data.evidence_refs[0].organization_id='B';
   if(control.unrenderable&&suffix.startsWith('/candidates')&&!suffix.endsWith('/evidence'))data.candidates[0].edges[0].target='unknown-step';
   try{return await reply(data);}catch{return;}
  }
  const dist=path.join(root,'apps/web/dist'),file=path.resolve(dist,'.'+(u.pathname==='/'?'/index.html':u.pathname));if(u.pathname==='/favicon.ico')return route.fulfill({status:204,body:''});if(!file.startsWith(dist+path.sep)||!fs.existsSync(file))return route.abort();return route.fulfill({body:fs.readFileSync(file),contentType:file.endsWith('.js')?'text/javascript':file.endsWith('.css')?'text/css':'text/html'});
 });
 function doc(){return {...structuredClone(first.document),active:!!control.active,registered:!control.retired,state:control.documentState||'completed'};}
 let sequence=0;
 async function boot(options={}){control={...options};await page.setViewportSize({width:1440,height:1050});await page.goto('http://127.0.0.1:4173/?flow='+(++sequence)+'#/documents');await page.getByRole('row').filter({hasText:first.document.original_name}).getByRole('button',{name:/상세 보기/}).click();await page.locator('.document-flow').waitFor();await page.waitForTimeout(80);}
 async function ready(){await page.getByRole('button',{name:'청킹 요청·상태 확인',exact:true}).click();await page.getByRole('button',{name:'이 버전 활성화',exact:true}).waitFor();}
 async function confirm(){await page.getByRole('button',{name:'이 버전 활성화',exact:true}).click();await page.getByRole('button',{name:'활성화 확인',exact:true}).click();}
 async function check(name,fn){try{await fn();results.push({name,status:'PASS'});console.log('PASS '+name);}catch(e){results.push({name,status:'FAIL',error:e.message});console.log('FAIL '+name+': '+e.message);}}
 const captures=path.resolve(root,process.env.V02B_CAPTURE_DIR||'outputs/v02b/ui');
 async function capture(name){fs.mkdirSync(captures,{recursive:true});const p=path.join(captures,name);if(fs.existsSync(p))throw Error('new capture required');await page.screenshot({path:p,fullPage:true});}
 try{
 await check('processing version cannot activate',async()=>{await boot({parseState:'processing',documentState:'processing'});assert.equal(await page.getByRole('button',{name:'이 버전 활성화',exact:true}).count(),0);assert.match(await page.locator('.document-flow').innerText(),/원문 처리 중에는 활성화할 수 없습니다/);});
 await check('unconfirmed chunk never implies completion or auto request',async()=>{await boot();assert.match(await page.locator('.document-flow').innerText(),/청킹 작업 ID가 미확인/);assert.equal(control.chunks||0,0);assert.equal(await page.getByRole('button',{name:'이 버전 활성화',exact:true}).count(),0);});
 await check('queued chunk and failed chunk have distinct next actions',async()=>{await boot({chunkState:'queued'});await page.getByRole('button',{name:'청킹 요청·상태 확인',exact:true}).click();await page.getByText('청킹 완료 후 상태를 확인하면 활성화할 수 있습니다.',{exact:true}).waitFor();assert.equal(await page.getByRole('button',{name:'이 버전 활성화',exact:true}).count(),0);control.chunkState='failed';await page.getByRole('button',{name:'청킹 상태 새로고침',exact:true}).click();await page.getByRole('button',{name:'청킹 재시도',exact:true}).waitFor();});
 await check('failed parsing exposes retry instead of activation',async()=>{await boot({parseState:'failed'});await page.getByRole('button',{name:'파싱 재시도',exact:true}).waitFor();assert.equal(await page.getByRole('button',{name:'이 버전 활성화',exact:true}).count(),0);});
 await check('registered/completed version is required in addition to chunks',async()=>{await boot({documentState:'processing'});await page.getByRole('button',{name:'청킹 요청·상태 확인',exact:true}).click();await page.waitForTimeout(50);assert.equal(await page.getByRole('button',{name:'이 버전 활성화',exact:true}).count(),0);});
 await check('activation requires confirmation, cancel/escape restore focus and send nothing',async()=>{await boot();await ready();await page.getByRole('button',{name:'이 버전 활성화',exact:true}).click();assert.equal(await page.evaluate(()=>document.activeElement.textContent),'취소');assert.match(await page.locator('dialog[open]').innerText(),/현재 활성 버전: 없음/);await page.keyboard.press('Escape');assert.equal(control.activations||0,0);assert.equal(await page.evaluate(()=>document.activeElement.textContent),'이 버전 활성화');await capture('activation-desktop.png');});
 await check('explicit double click sends one activation and rechecks server before workflow link',async()=>{await boot({activateDelay:200});await ready();const from=calls.length;await page.getByRole('button',{name:'이 버전 활성화',exact:true}).click();await page.getByRole('button',{name:'활성화 확인',exact:true}).evaluate(b=>{b.click();b.click();});await page.locator('.document-flow').getByRole('link',{name:'업무절차 후보 검토',exact:true}).waitFor();assert.equal(control.activations,1);assert.ok(calls.slice(from).filter(c=>c.method==='GET'&&c.path.includes('/versions/')).length>=4);assert.equal(await page.getByRole('button',{name:'이 버전 활성화',exact:true}).count(),0);await capture('active-desktop.png');});
 for(const code of [409,403,404,500])await check('activation HTTP '+code+' never claims success',async()=>{await boot({activateError:code});await ready();await confirm();await page.locator('[role=alert]').waitFor();assert.equal(await page.locator('.document-flow').getByRole('link',{name:'업무절차 후보 검토',exact:true}).count(),0);assert.equal(control.activations,1);});
 await check('network failure leaves activation uncertain and requires server refresh',async()=>{await boot({activateNetwork:true});await ready();await confirm();await page.locator('[role=alert]').waitFor();assert.match(await page.locator('[role=alert]').innerText(),/재조회 전까지 확정하지 않습니다/);assert.equal(await page.locator('.document-flow').getByRole('link').count(),0);});
 await check('lost activation response is uncertain until explicit server requery',async()=>{await boot({activateLost:true});await ready();await confirm();await page.locator('[role=alert]').waitFor();assert.equal(await page.locator('.document-flow').getByRole('link').count(),0);await page.getByRole('button',{name:'다시 시도',exact:true}).click();await page.locator('.document-flow').getByRole('link',{name:'업무절차 후보 검토',exact:true}).waitFor();assert.equal(control.activations,1);});
 await check('failed post-activation verification cannot advertise success',async()=>{await boot({failVerification:true});await ready();await confirm();await page.locator('[role=alert]').waitFor();assert.equal(await page.locator('.document-flow').getByRole('link').count(),0);control.failVerification=false;await page.getByRole('button',{name:'다시 시도',exact:true}).click();await page.locator('.document-flow').getByRole('link',{name:'업무절차 후보 검토',exact:true}).waitFor();assert.equal(control.activations,1);});
 await check('parse attempt change during confirmation prevents POST',async()=>{await boot();await ready();control.newAttempt=true;await confirm();await page.locator('[role=alert]').waitFor();assert.equal(control.activations||0,0);});
 await check('active version changed before confirmation prevents POST and shows current version',async()=>{await boot();await ready();control.active=true;await confirm();await page.locator('[role=alert]').waitFor();assert.equal(control.activations||0,0);});
 await check('mixed-version chunk response is rejected',async()=>{await boot({mixedChunk:true});await page.getByRole('button',{name:'청킹 요청·상태 확인',exact:true}).click();await page.locator('[role=alert]').waitFor();assert.equal(await page.getByRole('button',{name:'이 버전 활성화',exact:true}).count(),0);});
 await check('deregistered document cannot be activated',async()=>{await boot({retired:true});assert.equal(await page.getByRole('button',{name:'이 버전 활성화',exact:true}).count(),0);assert.equal(await page.getByRole('button',{name:'청킹 요청·상태 확인',exact:true}).count(),0);});
 await check('reader has query only and no activation or chunk mutation',async()=>{await boot({role:'reader',active:true});assert.match(await page.locator('.document-flow').innerText(),/직원 계정은 문서 조회만/);assert.equal(await page.getByRole('button',{name:'이 버전 활성화',exact:true}).count(),0);assert.equal(await page.locator('.document-flow').getByRole('link').count(),0);assert.equal(await page.getByRole('button',{name:'청킹 요청·상태 확인',exact:true}).count(),0);});
 await check('late activation cannot replace newly selected document',async()=>{await boot({activateDelay:700});await ready();await confirm();await page.getByRole('row').filter({hasText:pdf.document.original_name}).getByRole('button',{name:/상세 보기/}).click();await page.locator('.document-detail h3').first().filter({hasText:pdf.document.original_name}).waitFor();await page.waitForTimeout(900);assert.match(await page.locator('.document-detail').innerText(),new RegExp(pdf.document.original_name.replace('.','\.')));assert.doesNotMatch(await page.locator('.document-flow').innerText(),/활성화 후 서버 상태를 다시 확인했습니다/);});
 await check('workflow route selects exact server-allowed active document/version',async()=>{await boot({active:true});await page.locator('.document-flow').getByRole('link',{name:'업무절차 후보 검토',exact:true}).click();await page.locator('.wf-original-quote').waitFor();assert.equal(await page.getByLabel('문서',{exact:true}).inputValue(),first.document.document_id);assert.equal(await page.getByLabel('문서 버전',{exact:true}).inputValue(),first.document.id);});
 for(const query of ['document=not-allowed&version=unknown',`document=${first.document.document_id}&version=old-version`])await check('untrusted workflow query is rejected '+query,async()=>{control={active:true};await page.goto('http://127.0.0.1:4173/#/workflows?'+query);await page.getByText('이동한 문서·버전을 현재 활성 자료로 확인할 수 없습니다.',{exact:false}).waitFor();assert.equal(await page.locator('.wf-original-quote').count(),0);assert.equal(await page.getByRole('button',{name:'추출 작업 요청',exact:true}).count(),0);});
 await check('inactive query never silently falls back to other active document',async()=>{control={};await page.goto(`http://127.0.0.1:4173/#/workflows?document=${first.document.document_id}&version=${first.document.id}`);await page.getByText('이동한 문서·버전을 현재 활성 자료로 확인할 수 없습니다.',{exact:false}).waitFor();assert.equal(await page.locator('.wf-original-quote').count(),0);});
 await check('activation buttons reflow and dialog keyboard works at 320/375/768',async()=>{await boot();await ready();for(const width of [320,375,768]){await page.setViewportSize({width,height:812});assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));}await page.setViewportSize({width:375,height:812});await page.getByRole('button',{name:'이 버전 활성화',exact:true}).click();await capture('activation-mobile.png');await page.keyboard.press('Escape');});
 await check('no external requests, browser exceptions or sensitive browser cache',async()=>{assert.deepEqual(external,[]);assert.deepEqual(errors,[]);assert.equal(await page.evaluate(()=>localStorage.length+sessionStorage.length),0);});
 } finally {await browser.close();}
 const report={scope:'v0.2-B production UI + synthetic mock HTTP; not real backend integration',results,counts:{PASS:results.filter(r=>r.status==='PASS').length,FAIL:results.filter(r=>r.status==='FAIL').length},seconds:(performance.now()-started)/1000,external,errors,actual_external_provider_calls:0};fs.writeFileSync(output,JSON.stringify(report,null,2));console.log(JSON.stringify(report.counts));if(report.counts.FAIL)process.exitCode=1;
})().catch(e=>{console.error(e);process.exitCode=1;});
